import copy
import logging
from functools import reduce
from typing import Any, Protocol, abstractmethod

import schema

from trudag.config.schemas import (
    GENERAL_CONFIG_SCHEMA,
)
from trudag.dotstop.core.constants import DEFAULT_GENERAL_CONFIG
from trudag.dotstop.core.exception import ConfigError

logger = logging.getLogger(__name__)


class TrustableConfig(Protocol):
    """
    Protocol to support different kinds of configuration to be used in the trustable project.
    It has a basic requirement to support schema accessor, version of configuration, and configuration content.
    """

    content: dict[str, Any] = {}

    @property
    @abstractmethod
    def schema(self) -> schema.Schema:
        """
        Getter method to be implemented for returning the schema used in the configuration.
        Returns:
            `trudag.config.schema.Schema` of the configuration that validates the configuration content.
        """
        ...

    @property
    @abstractmethod
    def version(self) -> str:
        """
        Method to implemented to access the version of configuration
        """
        ...


class GeneralConfig(TrustableConfig):
    def __init__(self, content: dict[str, Any]):
        """
        Given a custom configuration list, validates it.
        Given no configuration, uses the default configuration in trudag.
        """
        self.content = copy.deepcopy(DEFAULT_GENERAL_CONFIG)
        self.override_config(content or {})
        self._validate()

    def _validate(self):
        try:
            self.schema.validate(self.content)
        except schema.SchemaError as exception:
            msg = f"Invalid data received from configuration content: {exception}"
            raise ConfigError(msg) from exception

    def override_config(self, custom_config: dict[str, Any]):
        """
        Overrides the configuration content with the given `custom_config` content.
        """

        def _update(content, new_content):
            for key, new_value in new_content.items():
                if isinstance(new_value, dict):
                    content[key] = _update(content.get(key, {}), new_value)
                else:
                    content[key] = new_value
            return content

        _update(self.content, custom_config)
        self._validate()

    @property
    def schema(self) -> schema.Schema:
        return GENERAL_CONFIG_SCHEMA

    @property
    def version(self) -> str:
        return self.content["version"]

    def safe_get(
        self, keys: list[str], config_content: dict[str, Any] | None = None
    ) -> Any:
        """
        Provides a safe way to search for values in the sub-sections of the configuration by recursively searching for the value of a given keys list.
        If given keys don't exist in the configuration, we fallback on the default general config.
        For example: get(["reports", "TSF", "enable_figures"]) will return the value for enable figures under the TSF report (.i.e. False).
        """
        value = self.get(keys, config_content)
        if value is None:
            if value := self.get(keys, DEFAULT_GENERAL_CONFIG):
                return value
            raise ConfigError(
                f"No value found for the keys: {', '.join(keys)} in the fallback default configuration!"
            )
        return value

    def get(
        self, keys: list[str], config_content: dict[str, Any] | None = None
    ) -> Any | None:
        """
        Provides a way to search for values in the sub-sections of the configuration by recursively searching for the value of a given keys list.
        For example: get(["reports", "TSF", "enable_figures"]) will return the value for enable figures under the TSF report (.i.e. False).
        """
        if not config_content:
            config_content = self.content

        return reduce(
            lambda d, key: d[key] if d and d.get(key, None) else None,
            keys,
            config_content,
        )

    def __eq__(self, other: "TrustableConfig") -> bool:
        return self.content == other.content and self.schema == other.schema
